import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>JPG وPNG هما أقدم صيغتي صور على الويب، وتحلان مشكلتين متعاكستين. واحدة صغيرة وعالمية، والأخرى دقيقة وشفافة.</p>\n<p>الفرق الأكثر سوء فهم بينهما هو الشفافية. JPG لا يستطيع حفظها أبدًا، وPNG يحفظها دائمًا.</p>\n<p>يقارن هذا المقال الصيغتين بصدق، لتختار الصيغة الصحيحة في كل مرة.</p>\n<h2 id=\"jpg-at-a-glance\">JPG باختصار</h2>\n<p>JPG باختصار: صيغة ضغط مع فقدان، صغيرة وعالمية. يعمل في كل مكان، لكنه لا يدعم الشفافية أبدًا.</p>\n<p>JPG مناسب للصور الفوتوغرافية، حيث الحجم الصغير أهم من الدقة الكاملة. كل بكسل له لون صلب.</p>\n<h2 id=\"png-at-a-glance\">PNG باختصار</h2>\n<p>PNG باختصار: صيغة ضغط دون فقدان، تدعم الشفافية الكاملة. يحفظ كل بكسل بدقة، بما فيه البكسلات الشفافة.</p>\n<p>PNG مناسب للرسوم والشعارات والنصوص، حيث الحواف الحادة والشفافية مهمة. لكن ملفاته أكبر بكثير.</p>\n<h2 id=\"what-transparency-is\">ما الشفافية فعلًا؟</h2>\n<p>ما الشفافية فعلًا؟ قناة ألفا في الصورة تحدد شفافية كل بكسل. بكسل شفاف يسمح برؤية ما خلفه، وبكسل صلب يحجبه.</p>\n<p>الشفافية ليست لونًا أبيض ولا خلفية فارغة. إنها معلومة إضافية في الملف تخبر البرنامج بأن هذا البكسل شفاف.</p>\n<h2 id=\"when-transparency-matters\">متى تهم الشفافية فعلًا؟</h2>\n<p>متى تهم الشفافية فعلًا؟ عندما تضع شعارًا على خلفية ملونة، أو أيقونة على صورة، أو ملصقًا على تصميم. بدون شفافية، يظهر مربع أبيض قبيح.</p>\n<p>الشفافية مهمة أيضًا للعلامات المائية والتراكبات. أي عنصر يوضع فوق شيء آخر يحتاج إلى شفافية.</p>\n<h2 id=\"when-it-does-not-matter\">متى لا تهم الشفافية؟</h2>\n<p>متى لا تهم الشفافية؟ عندما تكون الصورة مستطيلة كاملة تملأ مساحتها، مثل صورة فوتوغرافية أو خلفية. لا يوجد شيء خلفها ليظهر.</p>\n<p>للصور الفوتوغرافية، الشفافية عديمة الفائدة. JPG هو الخيار الصحيح دائمًا في هذه الحالة.</p>\n<h2 id=\"converting-cannot-add-transparency\">لماذا لا يستطيع التحويل إضافة شفافية؟</h2>\n<p>لماذا لا يستطيع التحويل إضافة شفافية؟ لأن JPG لا يحمل معلومات شفافية أصلًا. التحويل إلى PNG لا يخلق معلومات غير موجودة.</p>\n<p>الخلفية البيضاء في JPG تبقى بيضاء في PNG. لإزالة الخلفية، تحتاج إلى أداة إزالة خلفية لا إلى تحويل صيغة.</p>\n<h2 id=\"file-size-compared\">حجم الملف بمقارنة صادقة</h2>\n<p>حجم الملف بمقارنة صادقة: PNG أكبر من JPG بعدة مرات للصور الفوتوغرافية. صورة JPG بحجم 200 كيلوبايت قد تصبح PNG بحجم 1 ميغابايت.</p>\n<p>للرسوم والنصوص، الفرق أصغر. PNG مناسب للرسوم لأنها تحتوي على ألوان قليلة ومساحات صلبة تضغط جيدًا.</p>\n<h2 id=\"text-and-sharpness\">حدة النص والرسوم الخطية</h2>\n<p>حدة النص والرسوم الخطية: PNG يحفظ النصوص والخطوط بوضوح كامل. JPG يتجاهل التفاصيل الدقيقة، فيبدو النص ضبابيًا قليلًا.</p>\n<p>للرسوم ذات النصوص، استخدم PNG دائمًا. الفرق في الوضوح واضح بالعين المجردة.</p>\n<h2 id=\"photos-compared\">الصور الفوتوغرافية: JPG يفوز وPNG يخسر</h2>\n<p>الصور الفوتوغرافية: JPG يفوز وPNG يخسر. JPG أصغر بكثير بالجودة نفسها تقريبًا، وPNG يهدر المساحة دون أي فائدة.</p>\n<p>لا تستخدم PNG للصور الفوتوغرافية أبدًا. لا يوجد سبب وجيه لذلك، والملف الأكبر يبطئ كل شيء.</p>\n<h2 id=\"choosing-for-web\">كيف تختار للويب؟</h2>\n<p>كيف تختار للويب؟ استخدم PNG للشعارات والأيقونات والرسوم، وJPG أو WebP للصور الفوتوغرافية. كل نوع له صيغته المناسبة.</p>\n<p>للويب الحديث، فكر في WebP أيضًا. WebP يدعم الشفافية وأصغر من PNG بكثير.</p>\n<h2 id=\"choosing-for-print\">كيف تختار للطباعة؟</h2>\n<p>كيف تختار للطباعة؟ استخدم PNG للرسوم والنصوص الشفافة، وJPG بجودة عالية للصور الفوتوغرافية. الطباعة تحتاج دقة كاملة.</p>\n<p>للشعارات المطبوعة، احفظها كـPNG بدقة عالية أو كملف متجه. الحواف الحادة مهمة في الطباعة.</p>\n<h2 id=\"practical-rule\">قاعدة عملية لتتذكرها</h2>\n<p>قاعدة عملية لتتذكرها: إذا كانت الصورة تحتاج إلى شفافية، فاستخدم PNG. إذا كانت صورة فوتوغرافية، فاستخدم JPG.</p>\n<p>هذه القاعدة تغطي معظم الحالات. عندما تشك، فكر في السؤال: هل يوجد شيء خلف هذه الصورة يجب أن يظهر؟</p>\n<h2 id=\"logos-dark-backgrounds\">الشعارات على خلفيات داكنة</h2>\n<p>الشعارات على خلفيات داكنة: استخدم PNG شفافًا. الشعار الشفاف يتكيف مع أي خلفية، داكنة كانت أم فاتحة.</p>\n<p>شعار JPG على خلفية داكنة يظهر بمربع أبيض قبيح. الشفافية ليست رفاهية هنا، بل ضرورة.</p>\n<h2 id=\"icons-apps-websites\">الأيقونات للتطبيقات والمواقع الإلكترونية</h2>\n<p>الأيقونات للتطبيقات والمواقع الإلكترونية: استخدم PNG شفافًا. الأيقونات توضع فوق خلفيات متنوعة وتحتاج إلى شفافية.</p>\n<p>للأيقونات الصغيرة، PNG مناسب لأن الملفات صغيرة أصلًا. الحجم ليس مشكلة في هذه الحالة.</p>\n<h2 id=\"stickers-social-graphics\">الملصقات والرسوم الاجتماعية</h2>\n<p>الملصقات والرسوم الاجتماعية: استخدم PNG شفافًا. الملصقات توضع فوق الصور والخلفيات، والشفافية تجعلها تبدو احترافية.</p>\n<p>للملصقات دون شفافية، استخدم JPG. لكن معظم الملصقات تحتاج إلى شفافية لتبدو جيدة.</p>\n<h2 id=\"watermarks-overlays\">العلامات المائية والتراكبات</h2>\n<p>العلامات المائية والتراكبات: استخدم PNG شفافًا. العلامة المائية يجب أن تسمح برؤية الصورة خلفها.</p>\n<p>علامة مائية JPG تحجب جزءًا من الصورة بمربع صلب. PNG الشفاف هو الخيار الصحيح دائمًا هنا.</p>\n<h2 id=\"choosing-format-new-project\">كيف تختار صيغة لمشروع جديد؟</h2>\n<p>لاختيار صيغة لمشروع جديد، فكر في نوع الصور أولًا: شعارات ورسوم تعني PNG، وصور فوتوغرافية تعني JPG أو WebP.</p>\n<p>وللتحويل بين الصيغتين، استخدم <a href=\"/ar/tahwil-jpg-ila-png/\">محول JPG إلى PNG</a> و<a href=\"/ar/tahwil-png-ila-jpg/\">محول PNG إلى JPG</a>. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-tahwil-jpg-ila-png/\">الدليل الكامل لتحويل JPG إلى PNG</a> و<a href=\"/ar/blog/dalil-tahwil-png-ila-jpg/\">الدليل الكامل لتحويل PNG إلى JPG</a> و<a href=\"/ar/blog/kayfiyya-tahwil-jpg-ila-png/\">كيفية تحويل JPG إلى PNG</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يمكن أن يكون لملف JPG خلفية شفافة؟","answer":"لا، JPG لا يستطيع أن يكون له خلفية شفافة أبدًا. الصيغة لا تدعم قناة ألفا، وكل بكسل فيها له لون صلب."},{"question":"هل تحويل JPG إلى PNG يجعل الخلفية البيضاء شفافة؟","answer":"لا، التحويل لا يجعل الخلفية البيضاء شفافة. PNG المحوّل يحفظ الخلفية البيضاء كما هي، لأن التحويل لا يخلق شفافية."},{"question":"PNG أم JPG أفضل لشعار على موقع إلكتروني؟","answer":"PNG أفضل للشعار على موقع إلكتروني، لأنه يحفظ الشفافية والحواف الحادة. JPG مناسب فقط إذا كان للشعار خلفية صلبة."},{"question":"لماذا تبدو اللقطات أفضل كـPNG منها كـJPG؟","answer":"لأن PNG ضغط دون فقدان يحفظ الحواف الحادة والنصوص بوضوح. JPG يتجاهل التفاصيل الدقيقة، فيبدو النص ضبابيًا قليلًا."},{"question":"هل يمكنني استخدام PNG لكل صور موقعي الإلكتروني؟","answer":"لا، لا تستخدم PNG لكل صور موقعك. الصور الفوتوغرافية كـPNG ضخمة وتبطئ الموقع. استخدم JPG أو WebP للصور الفوتوغرافية."},{"question":"بأي صيغة أحفظ شعارًا شفافًا للطباعة؟","answer":"احفظ الشعار الشفاف للطباعة كـPNG بدقة عالية أو كملف متجه. PNG يحفظ الشفافية والحواف الحادة التي تحتاجها الطباعة."}];
